<script>if(localStorage.getItem('admin-theme')==='dark'||localStorage.getItem('theme')==='dark')document.documentElement.classList.add('dark')</script></head>
<body class="min-h-screen bg-neutral-50 dark:bg-neutral-950 text-neutral-900 dark:text-white"><main class="max-w-3xl mx-auto p-6 space-y-6"><div class="flex justify-between items-center"><a class="text-xs text-indigo-600 dark:text-indigo-400" href="/admin/support-overview">← Back to Customer Support</a><button id="theme" class="text-xs px-3 py-2 border border-neutral-300 dark:border-neutral-700 rounded-lg">Light / Dark</button></div><div><h1 class="text-2xl font-bold">Social Hub Installation</h1><p class="text-sm text-neutral-500 mt-2">Configure the website's API connection. Existing Facebook messaging continues independently.</p></div>
<form id="installation" class="bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-2xl p-6 space-y-4">
@foreach(['hub_url'=>'Hub URL','client_id'=>'Client ID','key_id'=>'Key ID','registered_domain'=>'Registered domain','secret'=>'API Secret'] as $name=>$label)
<div><label for="{{ $name }}" class="block text-xs font-semibold mb-2">{{ $label }}</label><input id="{{ $name }}" name="{{ $name }}" type="{{ $name==='secret'?'password':'text' }}" autocomplete="off" class="w-full px-3 py-2 text-sm bg-neutral-50 dark:bg-neutral-950 border border-neutral-300 dark:border-neutral-700 rounded-lg" @if($name!=='secret') required @endif></div>
@endforeach
<p class="text-xs text-neutral-500">Leave Secret blank to keep the existing key. A new client or key ID requires its Secret.</p><label class="flex gap-2 text-sm"><input type="checkbox" id="enabled">Enable API installation</label><div class="flex gap-3"><button class="px-4 py-2 bg-indigo-600 text-white text-sm rounded-lg">Save installation</button><button id="heartbeat" type="button" class="px-4 py-2 border border-neutral-300 dark:border-neutral-700 text-sm rounded-lg">Send heartbeat</button></div><p id="result" role="status" class="text-sm text-neutral-500"></p></form></main>
<script>
const form=document.querySelector('#installation'),result=document.querySelector('#result');
async function api(path,method='GET',data){const r=await fetch('/admin/api/social-hub/'+path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:data===undefined?undefined:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.message||'Request failed');return d}
async function load(){const d=await api('installation');const s=d.installation;if(s){for(const key of ['hub_url','client_id','key_id','registered_domain'])document.getElementById(key).value=s[key];document.querySelector('#enabled').checked=!!s.enabled;result.textContent='Last heartbeat: '+(s.last_heartbeat_status||'Never checked')+(s.last_heartbeat_at?' · '+s.last_heartbeat_at:'')}else document.querySelector('#hub_url').value='https://social.jwaistudio.online'}
form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const d=Object.fromEntries(new FormData(form));d.enabled=document.querySelector('#enabled').checked;await api('installation','PUT',d);document.querySelector('#secret').value='';await load();result.textContent='Installation saved. Send a heartbeat to verify.'}catch(e){result.textContent=e.message}finally{button.disabled=false}});
document.querySelector('#heartbeat').onclick=async e=>{e.target.disabled=true;result.textContent='Sending heartbeat…';try{const d=await api('heartbeat','POST');await load();result.textContent=d.ok?'Website → Hub verified':d.reason}catch(e){result.textContent=e.message}finally{e.target.disabled=false}};
document.querySelector('#theme').onclick=()=>{document.documentElement.classList.toggle('dark');localStorage.setItem('admin-theme',document.documentElement.classList.contains('dark')?'dark':'light')};load().catch(e=>result.textContent=e.message);
</script></body></html>
